import { useParams } from "react-router-dom";
import { useResults } from "../context/ResultsContext";
import { updateDecision } from "../api";

export default function CandidateDetail() {
  const { id } = useParams();
  const { results, setResults } = useResults();
  const candidate = results[id];

  if (!candidate) {
    return (
      <div className="page">
        <div className="container">
          <p>Candidate not found</p>
        </div>
      </div>
    );
  }

  const handleDecisionUpdate = async (decision) => {
    try {
      await updateDecision(id, decision);

      const updated = [...results];
      updated[id].decision = decision;
      setResults(updated);
    } catch (err) {
      alert("Failed to update decision");
    }
  };

  return (
    <div className="page">
      <div className="container">
        <h2>{candidate.filename}</h2>
        <p>
          {candidate.decision} • {candidate.final_score}%
        </p>

        {candidate.decision === "Review Later" && (
          <div style={{ marginBottom: "16px" }}>
            <button
              onClick={() => handleDecisionUpdate("Shortlisted")}
              style={{ marginRight: "8px" }}
            >
              Approve
            </button>
            <button onClick={() => handleDecisionUpdate("Rejected")}>
              Reject
            </button>
          </div>
        )}

        <div className="card">
          <h4>Strengths</h4>
          <ul>
            {candidate.ai?.strengths?.map((s, i) => (
              <li key={i}>{s}</li>
            ))}
          </ul>

          <h4 style={{ marginTop: "16px" }}>Red Flags</h4>
          <ul>
            {candidate.ai?.red_flags?.map((rf, i) => (
              <li key={i}>{rf}</li>
            ))}
          </ul>

          <h4 style={{ marginTop: "16px" }}>Rule Checks</h4>
          <ul>
            <li>
              Missing Mandatory Skills:{" "}
              {candidate.rules?.mandatory_skills?.missing?.length > 0
                ? candidate.rules.mandatory_skills.missing.join(", ")
                : "None"}
            </li>
            <li>
              GitHub Profile: {candidate.github ? "Provided" : "Not Provided"}
            </li>
          </ul>
        </div>
      </div>
    </div>
  );
}
